#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Kind {
    Bool,
    Int,
    UInt,
    Float,
    Complex,
    Object,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct DType {
    kind: Kind,
    precedence: u8,
}

// Helper function: find the dtype with maximum precedence (must appear in the input)
fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Since input is non-empty, safe to unwrap.
    types.into_iter()
        .max_by_key(|dt| dt.precedence)
        .unwrap()
}

// Main function: find common type from array_types and scalar_types (at least one non-empty)
fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let array_max = if array_types.is_empty() {
        None
    } else {
        Some(find_max_precedence_type(array_types))
    };

    let scalar_max = if scalar_types.is_empty() {
        None
    } else {
        Some(find_max_precedence_type(scalar_types))
    };

    match (array_max, scalar_max) {
        (Some(a), None) => Some(a),
        (None, Some(s)) => Some(s),
        (Some(a), Some(s)) => {
            if a.kind == s.kind {
                // same kind → return maximum from array_types
                Some(a)
            } else {
                // different kind → return maximum from scalar_types
                Some(s)
            }
        }
        (None, None) => None, // both empty → no common dtype
    }
}